$string['subscriptiontpl_modernsubscription_cancelled_body'] = '<div style="font-family: Arial, sans-serif"><p><img src="{logo}" alt="{sitename}" style="max-height:40px"></p><p>Bonjour {fullname},</p><p>Votre abonnement <strong>{plan_name}</strong> a été résilié comme vous l\'avez demandé.</p><p>Vous conservez l\'accès jusqu\'à la fin de la période en cours, le <strong>{subscription_enddate}</strong>.</p><p>Après cette date, vous n\'aurez plus accès à :</p><pre style="background:#f6f8fa;padding:12px;border-radius:6px">{courses_list}</pre><p>Vous avez changé d\'avis ? Vous pouvez vous réabonner à tout moment.</p><p><a href="{subscription_url}" style="display:inline-block;padding:12px 24px;background:#0d6efd;color:#fff;text-decoration:none;border-radius:6px;">Me réabonner</a></p></div>';
