$string['subscriptiontpl_modernsubscription_expired_body'] = '<div style="font-family: Arial, sans-serif"><p><img src="{logo}" alt="{sitename}" style="max-height:40px"></p><p>Bonjour {fullname},</p><p>Votre abonnement <strong>{plan_name}</strong> a expiré.</p><p>Vous n\'avez plus accès aux cours suivants :</p><pre style="background:#f6f8fa;padding:12px;border-radius:6px">{courses_list}</pre><p>Pour retrouver l\'accès et poursuivre votre parcours, réabonnez-vous.</p><p><a href="{subscription_url}" style="display:inline-block;padding:12px 24px;background:#0d6efd;color:#fff;text-decoration:none;border-radius:6px;">Voir les formules d\'abonnement</a></p><p>Nous espérons vous revoir bientôt !</p></div>';
